<template>
  <div>
    <div class="container">
      <div class="App">
        <div style="display: flex; justify-content: space-between; align-items: center">

          <div style="padding: 8px; flex:1">
            <el-select  v-model="languagesArray" multiple filterable collapse-tags style="width: 100%"
                       placeholder="Selected Languages">
              <el-option v-for="item in languageData" :key="item.value" :label="item.label" :value="item.value">
              </el-option>
            </el-select>
          </div>

          <div>
            <el-button  :loading="isOutputLoading" @click="downloadAllPreviews()">Download all previews</el-button>
            <el-button type="primary" @click="handleOpenEditDrawer(false, null)" style="margin-right: 8px">Add Screenshot</el-button>
          </div>
        </div>

        <el-row>
          <el-col :span='isMobile? 12 : 6' v-for="item in screenPreview">
            <div class="drop-area"
                 @dragover.prevent @drop="handleDrop($event, item)"
                 @dragenter="item.isDragging = true"
                 @dragleave="item.isDragging = false"
                 :class="{ 'highlight-border': item.isDragging }">

              <div style="height: 40px; background-color: white; display: flex; justify-content: space-between; align-items: center">
                <h4 style="margin: 0"></h4>
                <el-button type="text" @click="handleOpenEditDrawer(true, item)" style="margin: 16px; font-weight: bold">Edit
                </el-button>
              </div>

              <screen-preview ref="screenRefs"
                              :class="{ 'highlight-border': item.isDragging }"
                              :key="item"
                              :canvas-width="previewWidth" :canvas-height="previewHeight"
                              :text="item.title"
                              :text-align="item.textAlign"
                              style="width: 100%;"
                              :background-color="item.color"
                              frame-img-url="/frames/google-pixel-4-xl-black.png"
                              :screen-blob-img="item.blob"></screen-preview>
            </div>

          </el-col>
        </el-row>

        <div v-for="lang in languagesArray">
          <span style="margin-top: 48px; margin-left: 8px">{{getLanguageLabel(lang)}}</span>
          <el-row>
                <el-col :span='isMobile? 12 : 6' v-for="item in screenPreview">
                  <div style="padding: 8px">

                    <screen-preview :ref="'screenRefs_' + lang"
                                    :class="{ 'highlight-border': item.isDragging }"
                                    :key="item"
                                    :canvas-width="previewWidth" :canvas-height="previewHeight"
                                    :text="item.translatedDesc[lang]"
                                    :text-align="item.textAlign"
                                    style="width: 100%;"
                                    :background-color="item.color"
                                    frame-img-url="/frames/google-pixel-4-xl-black.png"
                                    :screen-blob-img="item.blob"></screen-preview>
                  </div>

                </el-col>
          </el-row>

        </div>
      </div>

      <el-drawer
          :title="this.isEditDrawer? 'Edit Screenshot': 'Add Screenshot'"
          :visible.sync="isAddEditDrawerOpen"
          :size="isMobile? '100%' : '45%'"
          direction='rtl'>

        <div style="display: flex; flex-direction: column; height: 100%; width: 100%; padding: 16px">
          <el-button :loading="isTransLoading" @click="startTranslate(selectedPreview)">Translate</el-button>
          <el-form style="flex: 1; margin-top: 12px" ref="form" :model="selectedPreview" label-width="150px">
            <el-form-item label="Desc">
              <el-input type="textarea" resize="none" v-model="selectedPreview.title"></el-input>
            </el-form-item>

            <el-form-item v-for="item in languagesArray" :label="getLanguageLabel(item)">
              <el-input type="textarea" resize="none" v-model="selectedPreview.translatedDesc[item]"></el-input>
            </el-form-item>

            <el-form-item label="Text Align">
              <el-radio v-model="selectedPreview.textAlign" label="0">Left</el-radio>
              <el-radio v-model="selectedPreview.textAlign" label="1">Center</el-radio>
              <el-radio v-model="selectedPreview.textAlign" label="2">Right</el-radio>
            </el-form-item>

            <el-form-item label="Background">
              <el-color-picker v-model="selectedPreview.color"></el-color-picker>
            </el-form-item>
          </el-form>

          <div style="margin-bottom: 24px; display: flex; justify-content: space-between">
            <el-button style="flex: 1" @click="isAddEditDrawerOpen = false">Cancel</el-button>
            <el-button style="flex: 1" type="primary" @click="handleDrawerConfirmed()" :loading="loading">Confirm</el-button>
          </div>
        </div>

      </el-drawer>
    </div>
  </div>
</template>

<script>

import ScreenPreview from "@/components/ScreenPreview.vue";
import JSZip from 'jszip';
import FileSaver from 'file-saver'
import languages from "@/store/languages";
import {formatTranslate} from "@/api/user";


export default {
  components: {ScreenPreview},

  data() {
    return {
      isTransLoading: false,

      isMobile: false,
      isOutputLoading: false,
      languageData: [],
      languagesArray: ['ZH'],
      isAddEditDrawerOpen: false,
      isEditDrawer: false,
      previewWidth: 1080,
      previewHeight: 1920,
      selectedPreview: {},
      defaultImgBlob: null,
      screenPreview: [
        {
          title: "Input\ntext here",
          translatedDesc: {
            'ZH': '',
          },
          textAlign: 0,
          color: "#5ba5be",
          blob: null,
          isDragging: false,
        },
        {
          title: "Drag\nscreenshot here",
          translatedDesc: {
            'ZH': '',
          },
          textAlign: 0,
          color: "#ec71a8",
          blob: null,
          isDragging: false
        },
        {
          title: "Paste\ntranslate results",
          translatedDesc: {
            'ZH': '',
          },
          textAlign: 0,
          color: "#4faef8",
          blob: null,
          isDragging: false
        },
        {
          title: "Download\napp preview",
          translatedDesc: {
            'ZH': '',
          },
          textAlign: 0,
          color: "#a120f6",
          blob: null,
          isDragging: false
        }
      ],
    }
  },
  mounted() {
    this.selectedPreview = this.screenPreview[0]
    fetch('/frames/img_previews_demo.jpg')
        .then(response => response.blob())
        .then(blob => {
          this.defaultImgBlob = blob
          for (const item of this.screenPreview) {
            if (item.blob == null) {
              item.blob = this.defaultImgBlob
            }
          }
        })
        .catch(error => {
          console.error('blob error:', error);
        });

    const data = [];
    Object.keys(languages.state.allLanguages).forEach((item) => {
      data.push({
        label: languages.state.allLanguages[item],
        value: languages.state.languageKey[item],
      })
    })

    this.languageData = data;

    this.isMobile = window.innerWidth < 768;
    window.addEventListener('resize', this.checkMobile);


    const previewObject = localStorage.getItem("out_app_preview");
    if (previewObject) {
      this.screenPreview = JSON.parse(previewObject);
      for (const item of this.screenPreview) {
        item.blob = null
      }
    }
  },
  methods: {
    startTranslate(currentPreview) {
      if (currentPreview.title.length <= 0) {
        return;
      }
      this.isTransLoading = true
      let formData = new FormData()
      formData.append("files", this.stringToBlob(
          JSON.stringify(
              {"text": currentPreview.title, "context": 'Keep newlines'}
          )
      ))
      formData.append("source", "EN")
      formData.append("platform", "Text")
      formData.append("targets", this.languagesArray + "," + "EN");
      formatTranslate(formData).then((data) => {
        this.isTransLoading = false
        if (data.code == 200 && data.data != null) {
          const items = JSON.parse(data.data);
          for (const item of items) {
            currentPreview.translatedDesc[item.language] = item.content
          }
        }
      })
    },
    stringToBlob(binaryString) {
      console.log(binaryString)
      const encoder = new TextEncoder();
      const encodedContent = encoder.encode(binaryString);
      // 创建Blob对象
      return new Blob([encodedContent], {type: 'text/plain'});
    },
    checkMobile() {
      // 根据窗口宽度判断是否为移动设备
      this.isMobile = window.innerWidth < 768;
    },
    pastResult(selectedPreview) {
      if (navigator.clipboard) {
        // 读取剪贴板内容
        navigator.clipboard.readText().then(text => {
              const items = JSON.parse(text);
              for (const item of items) {
                if (item.language == 'EN') {
                  this.selectedPreview.title = item.content
                } else {
                  this.selectedPreview.translatedDesc[item.language] = item.content
                }
              }
            }).catch(err => {
              console.error("clipboard error:", err);
            });
      } else {
        console.warn("Clipboard API not supported.");
      }
    },
    getLanguageLabel(lang) {
      return languages.state.languages[lang]
    },
    handleOpenEditDrawer(isEdit, preview) {
      this.isEditDrawer = isEdit
      this.isAddEditDrawerOpen = true
      if (preview == null) {
        preview = {
          title: "",
          translatedDesc: {},
          blob: this.defaultImgBlob,
          isDragging: false,
        }
        for (const item of this.languagesArray) {
          preview.translatedDesc[item] = ""
        }
      }
      this.selectedPreview = preview
    },
    handleDrawerConfirmed() {
      if (!this.isEditDrawer) {
        if (this.selectedPreview.blob == null) {
          this.selectedPreview.blob = this.defaultImgBlob
        }
        this.screenPreview.push(this.selectedPreview)
      }
      this.isAddEditDrawerOpen = false
    },
    handleDrop(event, item) {
      event.preventDefault();
      this.isDragging = false
      const files = event.dataTransfer.files;
      if (0 < files.length) {
        item.blob = files[0]
      }
    },
    downloadAllPreviews() {
      this.isOutputLoading = true
      let zip = new JSZip()

      // deal default
      for (let i = 0; i < this.$refs.screenRefs.length; i++) {
        let file = this.$refs.screenRefs[i].exportImages()
        zip.file('default/' + file.name, file )
      }


      // translate
      for (let lang of this.languagesArray) {
        let folder = languages.state.languages[lang]
        for (let i = 0; i < this.$refs['screenRefs_' + lang].length; i++) {
          let file = this.$refs['screenRefs_' + lang][i].exportImages()
          zip.file(folder + '/' + file.name, file )
        }
      }


      // download
      zip.generateAsync({ type: 'blob' }).then(content => {
        this.isOutputLoading = false
        // 使用 FileSaver.js 下载 ZIP 文件
        FileSaver.saveAs(content, 'AppLocalize_Screenshots.zip');
      });
    }
  },
  watch: {
    screenPreview:  {
      handler: function (newVal, oldVal) {
        localStorage.setItem("out_app_preview", JSON.stringify(newVal));
      }, deep: true
    }
  }
}
</script>

